<div x-show="selectedStaff" x-cloak><button aria-label="Tutup detail" @click="selectedStaff=null" class="fixed inset-0 z-40 bg-slate-950/35 backdrop-blur-[2px]"></button><aside x-show="selectedStaff" x-transition:enter="transition duration-300" x-transition:enter-start="translate-x-full" x-transition:enter-end="translate-x-0" class="fixed inset-y-0 right-0 z-50 w-full max-w-md overflow-y-auto bg-white p-6 shadow-2xl"><button @click="selectedStaff=null" class="absolute right-5 top-5 rounded-full bg-slate-100 p-2">✕</button><template x-if="selectedStaff"><div>
    <div class="mt-5 flex items-center gap-4"><img :src="selectedStaff.avatar" :alt="selectedStaff.name" x-on:error="$event.target.onerror=null; $event.target.src=selectedStaff.avatar_fallback" class="h-20 w-20 rounded-full border-4 border-white object-cover shadow-xl"><div><h2 class="text-xl font-black" x-text="selectedStaff.name"></h2><p class="mt-1 text-sm text-ink-muted" x-text="selectedStaff.unit+' · '+selectedStaff.regional"></p><span class="mt-2 inline-flex rounded-full bg-blue-50 px-2.5 py-1 text-xs font-bold text-blue-700" x-text="status(selectedStaff)"></span></div></div>
    <div class="mt-7 rounded-2xl bg-slate-950 p-5 text-white"><div class="flex items-end justify-between"><div><p class="text-xs text-slate-400">Progress Hari Ini</p><strong class="mt-1 block text-3xl" x-text="`${selectedStaff.completed_daily} / ${selectedStaff.total_daily}`"></strong></div><b class="text-blue-300" x-text="percentage(selectedStaff).toFixed(0)+'%'"></b></div><div class="mt-4 h-2 overflow-hidden rounded-full bg-white/10"><div class="h-full rounded-full bg-gradient-to-r from-blue-500 to-cyan-400 transition-all duration-700" :style="`width:${percentage(selectedStaff)}%`"></div></div></div>
    <div class="mt-7"><h3 class="font-black">Aktivitas Daily</h3><div class="mt-3 space-y-2">@foreach(collect($activities)->where('category','DAILY') as $activity)<div class="flex items-center gap-3 rounded-xl border p-3" :class="selectedStaff.activities[@js($activity['key'])].done?'border-emerald-100 bg-emerald-50/60':'border-border'"><span class="grid h-8 w-8 place-items-center rounded-full" :class="selectedStaff.activities[@js($activity['key'])].done?'bg-emerald-500 text-white':(selectedStaff.activities[@js($activity['key'])].tracked?'bg-slate-100 text-slate-400':'bg-amber-100 text-amber-700')" x-text="selectedStaff.activities[@js($activity['key'])].done?'✓':(selectedStaff.activities[@js($activity['key'])].tracked?'○':'!')"></span><div class="min-w-0 flex-1"><b class="block text-sm">{{ $activity['short'] }}</b><span class="block text-xs text-ink-muted" x-text="selectedStaff.activities[@js($activity['key'])].done?'Selesai':(selectedStaff.activities[@js($activity['key'])].tracked?'Belum selesai':'Belum terintegrasi')"></span><span class="block text-[10px] text-ink-muted" x-text="selectedStaff.activities[@js($activity['key'])].source"></span></div><span class="text-xs font-semibold text-ink-muted" x-text="selectedStaff.activities[@js($activity['key'])].time||''"></span></div>@endforeach</div></div>
</div></template></aside></div>
